import { GIT_VALUE_OPTIONS } from "../../../kernel/gitopts.ts";
import { commands } from "../../../kernel/shell.ts";
import { baseName, stripWrappers } from "../../../kernel/wrappers.ts";

/** What a call does to the commit check: it skips the hook, it sets a git config for it, it sets or removes an env var of git config, or it writes a commit with the plumbing command that runs no hook. */
export type Bypass = "--no-verify" | "git config" | "env" | "git commit-tree";

/** The names of the env vars that change the git config of a command. */
const CONFIG_ENV =
  /^(?:GIT_CONFIG_(?:COUNT|KEY_\d+|VALUE_\d+|PARAMETERS|GLOBAL|SYSTEM|NOSYSTEM))$/;

/** The options of `git commit` that take the next word as their value. */
const COMMIT_VALUE_OPTIONS: ReadonlySet<string> = new Set([
  "-m",
  "-F",
  "-C",
  "-c",
  "-t",
  "--message",
  "--file",
  "--author",
  "--date",
  "--cleanup",
  "--template",
  "--reuse-message",
  "--reedit-message",
  "--fixup",
  "--squash",
  "--pathspec-from-file",
  "--trailer",
]);

/** The short options of `git commit` that end a cluster, because the rest of the cluster is their value. */
const SHORT_VALUE_LETTERS = "mFCctuS";

/** The config names that move or turn off the hooks: `core.hooksPath` and each `hook.*` key. */
const isHookConfig = (setting: string): boolean => {
  const name = (setting.split("=")[0] ?? "").toLowerCase();
  return name === "core.hookspath" || name.startsWith("hook.");
};

/** The git command in `argv`, as its global options and the words after them, or `undefined` for another command. */
const gitOf = (
  argv: string[],
): { settings: string[]; rest: string[] } | undefined => {
  const [head, ...words] = stripWrappers(argv);
  if (head === undefined || baseName(head) !== "git") return undefined;
  const settings: string[] = [];
  let i = 0;
  while (i < words.length && (words[i] as string).startsWith("-")) {
    const opt = words[i] as string;
    const value = words[i + 1] ?? "";
    if (opt === "-c" || opt === "--config-env") settings.push(value);
    if (opt.startsWith("--config-env=")) settings.push(opt.slice(13));
    i += GIT_VALUE_OPTIONS.has(opt) ? 2 : 1;
  }
  return { settings, rest: words.slice(i) };
};

/** True when the words after `commit` hold `--no-verify` (or a unique start of it) or a short cluster with `n`. */
const skipsHook = (args: string[]): boolean => {
  for (let i = 0; i < args.length; i++) {
    const arg = args[i] as string;
    if (arg === "--") return false;
    if (arg.startsWith("--")) {
      const name = arg.split("=")[0] as string;
      if (name.length >= 6 && "--no-verify".startsWith(name)) return true;
      if (COMMIT_VALUE_OPTIONS.has(name) && !arg.includes("=")) i++;
      continue;
    }
    if (!arg.startsWith("-") || arg.length < 2) continue;
    for (const letter of arg.slice(1)) {
      if (letter === "n") return true;
      if (SHORT_VALUE_LETTERS.includes(letter)) {
        if ("mFCct".includes(letter) && letter === arg.at(-1)) i++;
        break;
      }
    }
  }
  return false;
};

/** The shell commands whose words name variables: they set, export, or remove them. */
const VARIABLE_COMMANDS: ReadonlySet<string> = new Set([
  "export",
  "declare",
  "typeset",
  "readonly",
  "local",
  "unset",
]);

/** The name part of a word such as `NAME` or `NAME=value`. */
const nameOf = (word: string): string => word.split("=")[0] as string;

/** True when the `env` options in `before` remove the whole environment, or remove a name of the git config. */
const envClears = (before: string[]): boolean => {
  const at = before.findIndex((word) => baseName(word) === "env");
  if (at < 0) return false;
  for (let i = at + 1; i < before.length; i++) {
    const word = before[i] as string;
    if (/^\w+=/.test(word)) continue;
    if (word === "-" || word === "--ignore-environment") return true;
    if (word === "-u" || word === "--unset") {
      if (CONFIG_ENV.test(before[i + 1] ?? "")) return true;
      i++;
    } else if (word.startsWith("--unset=")) {
      if (CONFIG_ENV.test(word.slice(8))) return true;
    } else if (/^-[A-Za-z]/.test(word)) {
      const unset = word.indexOf("u");
      if (/^-[^u]*i/.test(word.slice(0, unset < 0 ? undefined : unset)))
        return true;
      if (unset >= 0) {
        const tail = word.slice(unset + 1);
        if (CONFIG_ENV.test(tail || (before[i + 1] ?? ""))) return true;
        if (!tail) i++;
      }
    } else break;
  }
  return false;
};

/**
 * True when `argv` sets or removes a variable of the git config:
 * an assignment before the command (`A=1 env B=2 git`), an `export`, `declare`, `typeset`, `readonly`, `local`, or `unset` of the name,
 * or an `env` that clears the environment or the name before `git`.
 */
const changesConfigEnv = (argv: string[]): boolean => {
  const rest = stripWrappers(argv);
  const before = argv.slice(0, Math.max(0, argv.length - rest.length));
  const assigned = before.map((word) => /^(\w+)=/.exec(word)?.[1] ?? "");
  const named = VARIABLE_COMMANDS.has(rest[0] ?? "")
    ? rest
        .slice(1)
        .filter((word) => !word.startsWith("-"))
        .map(nameOf)
    : [];
  if ([...assigned, ...named].some((name) => CONFIG_ENV.test(name)))
    return true;
  return baseName(rest[0] ?? "") === "git" && envClears(before);
};

/**
 * What in `text` skips the commit check, or `undefined` when nothing does.
 * It looks only at a text that runs `git commit`, except for `git commit-tree`, which it always reports.
 */
export const bypassOf = (text: string): Bypass | undefined => {
  const all = commands(text);
  const gits = all.flatMap((argv) => gitOf(argv) ?? []);
  const commits = gits.filter((git) => git.rest[0] === "commit");
  if (gits.some((git) => git.rest[0] === "commit-tree"))
    return "git commit-tree";
  if (commits.length === 0) return undefined;
  if (commits.some((git) => skipsHook(git.rest.slice(1)))) return "--no-verify";
  if (commits.some((git) => git.settings.some(isHookConfig)))
    return "git config";
  if (all.some(changesConfigEnv)) return "env";
  return undefined;
};

/** The options of `gh pr create` and `gh pr edit` that take a separate value, which is not the pull request. */
const VALUE_OPTIONS = new Set([
  "-t",
  "--title",
  "-b",
  "--body",
  "-F",
  "--body-file",
  "-B",
  "--base",
  "-H",
  "--head",
  "-l",
  "--label",
  "--add-label",
  "--remove-label",
  "-a",
  "--assignee",
  "--add-assignee",
  "--remove-assignee",
  "-r",
  "--reviewer",
  "--add-reviewer",
  "--remove-reviewer",
  "-m",
  "--milestone",
  "-p",
  "--project",
  "--add-project",
  "--remove-project",
  "-T",
  "--template",
  "--recover",
]);

/** Which `gh pr` command `argv` is, or `undefined`. The `-R` option and its value are skipped. */
const ghPr = (argv: string[]) => {
  const [head, ...words] = stripWrappers(argv);
  if (head === undefined || baseName(head) !== "gh") return undefined;
  const plain: string[] = [];
  let repo: string | undefined;
  for (let i = 0; i < words.length; i++) {
    const word = words[i] as string;
    if (word === "-R" || word === "--repo") repo = words[++i];
    else if (word.startsWith("--repo=")) repo = word.slice(7);
    else if (VALUE_OPTIONS.has(word)) i++;
    else if (!word.startsWith("-")) plain.push(word);
  }
  if (plain[0] !== "pr") return undefined;
  return { verb: plain[1], target: plain[2], repo };
};

/** A `gh pr create` or `gh pr edit` call of a text: the verb, the PR that `edit` names, and the `--repo` value. */
export type PrCall = {
  verb: "create" | "edit";
  target: string | undefined;
  repo: string | undefined;
};

/** The `gh pr create` and `gh pr edit` calls in `text`, in order. */
export const prCallsOf = (text: string): PrCall[] =>
  commands(text).flatMap((argv) => {
    const call = ghPr(argv);
    if (call?.verb !== "create" && call?.verb !== "edit") return [];
    return [{ verb: call.verb, target: call.target, repo: call.repo }];
  });
